#!/usr/bin/env python3
"""Generate Claude role entrypoints from the registry; never launch an agent."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def definitions(root=ROOT):
    registry = json.loads((root / 'agents/registry.json').read_text())
    result = {}
    for role in registry['roles']:
        read_only = 'Write' not in role['tools']
        persistence = ('Return reports and checkpoint text to the coordinator for persistence. '
                       'Do not edit product files or push changes.' if read_only else
                       'Write only assigned deliverables and checkpoints in the authorized workspace.')
        delegation = ('Coordinate child assignments using the available Agent tool; verify runtime support first.'
                      if role['id'] == 'studio-director' else
                      'Return specialist requests to the coordinator. This definition does not grant nested spawning.')
        result[role['definition']] = f"""---
name: {role['id']}
description: {role['description']}
tools: {', '.join(role['tools'])}
model: inherit
---

<!-- Generated by scripts/sync_agent_definitions.py. Edit agents/registry.json or the canonical prom.md instead. -->

You are the {role['id']} role. Before substantive work, read `CLAUDE.md`,
`agents/COMMON.md`, and `{role['prompt']}` completely, then the current
assignment and its latest checkpoint. Resolve these paths from this repository's
root, not an unrelated working directory. If a required contract is missing or
unreadable, report the exact missing path and return to the coordinator; do not
replace it with a guessed role description.

The canonical prompt defines your required inputs, procedure, outputs, acceptance
criteria, failure handling and completion report. Follow it together with the
shared contract. Do not interpret a short description as the complete task.

{persistence}
{delegation}

Organizational parent: `{role['parent'] or 'owner assignment'}`.
Existing dashboard category: `{role['dashboard_role']}`. This mapping does not
register a running worker or a new dashboard API role.

Preserve quality-first, private per-game evidence and the no-new-spend boundary.
Only the designated integration writer updates remote main after independent
review and checks; never force-push. Never approve a release, impersonate the
owner, use signing credentials, deploy production, or publish a game merely
because shell access exists. Report executed checks separately from plans.

Tool allowlists do not create OS isolation. Return unavailable-tool/device
requirements as concrete blockers. Checkpoint before context exhaustion and
handoff so the next session can resume from evidence.
"""
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Report drift without writing')
    args = parser.parse_args()
    stale = []
    for relative, content in definitions().items():
        target = ROOT / relative
        if not target.exists() or target.read_text() != content:
            stale.append(relative)
            if not args.check:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text(content)
    if args.check and stale:
        print('Agent definition drift:\n' + '\n'.join(stale))
        return 1
    print(f"{'Checked' if args.check else 'Synchronized'} {len(definitions())} agent definitions.")
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
